#!/usr/bin/env bash
# JARVIS-WORKS V5.15: disposable mutation-time payload digest review; source untouched.
set -Eeuo pipefail
export LC_ALL=C
if [[ "${JW_ENV:-}" =~ ^[[:space:]]*[Pp][Rr][Oo][Dd][Uu][Cc][Tt][Ii][Oo][Nn][[:space:]]*$ ]]; then
  echo 'BLOCKED: production environment denied'; exit 2
fi
for bin in git python3 sha256sum base64 tar docker node; do
  command -v "$bin" >/dev/null || { echo "BLOCKED: prerequisite $bin missing"; exit 2; }
done
repo="$(git rev-parse --show-toplevel 2>/dev/null)" || { echo 'BLOCKED: run inside JARVIS-WORKS'; exit 2; }
[[ "$(git -C "$repo" remote get-url origin)" == *"JARVIS-WORKS"* ]] || { echo 'BLOCKED: unexpected repository';exit 2; }
v58='e8ea684c9af78debdfc26179641e3094f2d2ef20'
v59='c9f78cd68e1dad8aab7947922a784d95806eab45'
git -C "$repo" cat-file -e "$v58^{commit}" || { echo 'BLOCKED: trusted V5.8 base missing';exit 2; }
git -C "$repo" fetch origin refs/heads/review/v59
[[ "$(git -C "$repo" rev-parse FETCH_HEAD)" == "$v59" ]] || { echo 'BLOCKED: trusted review/v59 ref changed';exit 2; }
git -C "$repo" merge-base --is-ancestor "$v58" "$v59" || { echo 'BLOCKED: V5.8 ancestor mismatch';exit 2; }
work='';old='';source_dir=''
cleanup() {
  result=$?
  trap - EXIT
  if [[ -n "$old" ]]; then git -C "$repo" worktree remove --force "$old" || result=1; fi
  if [[ -n "$work" ]]; then git -C "$repo" worktree remove --force "$work" || result=1; fi
  if [[ -n "$source_dir" ]]; then rm -rf -- "$source_dir" || result=1; fi
  if (( result != 0 )); then echo "FAIL: V5.15 review gate status=$result";
  else echo 'PASS: V5.15 review gates completed; cutover, push and merge DENIED'; fi
  exit "$result"
}
trap cleanup EXIT
source_dir="$(mktemp -d "${TMPDIR:-/tmp}/jw515-payload.XXXXXXXX")"
sed -n '/^__JW515_PAYLOAD__$/,$p' "${BASH_SOURCE[0]}" | tail -n +2 | base64 -d > "$source_dir/payload.tgz"
echo '28f8610c2f789c4964d3df8bcd44ab5de077823d2187915a99f2840211ea16be  '"$source_dir/payload.tgz" | sha256sum -c -
